<script setup lang="ts">
import { computed, reactive, ref } from 'vue';
const tabs = [
  { id: 'basic', name: '계약 기본정보', summary: '계약 기본정보와 비교 대상을 같은 업무 공간에서 검토합니다.', point: '계약을 전환해도 입력한 검토 메모와 선택한 탭을 복원합니다.' },
  { id: 'detail', name: '계약 상세정보', summary: '목적물·담보·위험 계층을 상품별 화면과 연결합니다.', point: '참고 계약과 현재 계약의 담보 탭을 대응시켜 같은 조건을 비교합니다.' },
  { id: 'terms', name: 'Terms&Conditions', summary: '계약 조건에 따른 약관을 선택하고 참고 계약과 비교합니다.', point: '같은 약관을 중복으로 추가하지 않고, 선택한 조건을 유지합니다.' },
  { id: 'rate', name: '요율산정', summary: '기본요율, 할인·할증과 제시보험료를 한 화면에서 검토합니다.', point: '실제 계산 응답은 계약·대상·입력 조건이 일치할 때만 반영합니다.' },
];
const contracts = reactive([
  { id: 'A', company: '예시 제조기업 A', memo: '시설 배상 담보를 검토합니다.', tab: 'basic', coverage: '시설 배상', clauses: ['시설 배상 특별약관'] },
  { id: 'B', company: '예시 서비스기업 B', memo: '참고 계약의 조건을 확인합니다.', tab: 'basic', coverage: '생산물 배상', clauses: ['생산물 배상 특별약관'] },
]);
const selected = ref(0);
const current = computed(() => contracts[selected.value]);
const active = computed(() => tabs.find(tab => tab.id === current.value.tab)!);
const mode = ref('assistant');
const copied = ref(false);
const status = ref('예시 계약 A의 검토 메모를 수정한 뒤 계약 B로 이동해 보세요.');
const clause = ref('교차배상책임 특별약관');
const changeContract = (index: number) => { selected.value = index; copied.value = false; status.value = `계약 ${current.value.id}의 입력과 탭을 복원했습니다.`; };
const copyMemo = () => { current.value.memo = '참고 계약: 보상한도와 자기부담금 조건을 함께 확인합니다.'; copied.value = true; status.value = 'Reference 검토 메모를 현재 계약에 복사했습니다.'; };
const addClause = () => {
  if (current.value.clauses.includes(clause.value)) { status.value = '이미 선택된 약관입니다. 중복 추가하지 않습니다.'; return; }
  current.value.clauses.push(clause.value); status.value = '현재 계약의 약관에 추가했습니다.';
};
</script>

<template>
  <div class="workspace-demo">
    <div class="ws-top"><img src="/assets/koreanre-logo.svg" alt="AI Assistant" /><span>특종보험 UW</span><span class="ws-sample">설명용 샘플</span></div>
    <div class="ws-app-shell"><nav class="ws-navigation" aria-label="샘플 업무 메뉴"><span class="ws-nav-label">UNDERWRITING</span><strong>특종보험 UW</strong><span class="ws-nav-item">접수 관리</span><span class="ws-nav-item ws-nav-active">계약 검토</span><span class="ws-nav-label">작업 중인 계약</span><button v-for="(contract, index) in contracts" :key="contract.id" type="button" :aria-pressed="index === selected" @click="changeContract(index)">계약 {{ contract.id }}</button><small>가상 계약으로 체험하는<br />프론트엔드 구현 사례</small></nav><div class="ws-work-area">
    <div class="ws-contracts"><span>← UW 목록 / 계약 검토</span><strong>UW-DEMO-{{ current.id }} · {{ current.company }}</strong></div>
    <div class="ws-tabs" aria-label="업무 탭"><button v-for="tab in tabs" :key="tab.id" type="button" :aria-pressed="current.tab === tab.id" @click="current.tab = tab.id">{{ tab.name }}</button></div>
